    r.add_lower_bounded_integer_option("max_soc", "Maximum number of second order correction trial steps at each iteration.", 0, 4, "Choosing 0 disables the second order corrections. This is p^{max} of Step A-5.9 of Algorithm A in the implementation paper.")?;
    r.add_lower_bounded_number_option("kappa_soc", "Factor in the sufficient reduction rule for second order correction.", 0.0, true, 0.99, "This option determines how much a second order correction step must reduce the constraint violation so that further correction steps are attempted. See Step A-5.9 of Algorithm A in the implementation paper.")?;
    r.add_lower_bounded_number_option("obj_max_inc", "Determines the upper bound on the acceptable increase of barrier objective function.", 1.0, true, 5.0, "Trial points are rejected if they lead to an increase in the barrier objective function by more than obj_max_inc orders of magnitude.")?;
    r.add_lower_bounded_integer_option("max_filter_resets", "Maximal allowed number of filter resets", 0, 5, "A positive number enables a heuristic that resets the filter, whenever in more than \"filter_reset_trigger\" successive iterations the last rejected trial steps size was rejected because of the filter. This option determine the maximal number of resets that are allowed to take place.")?;
    r.add_lower_bounded_integer_option("filter_reset_trigger", "Number of iterations that trigger the filter reset.", 1, 5, "If the filter reset heuristic is active and the number of successive iterations in which the last rejected trial step size was rejected because of the filter, the filter is reset.")?;
    r.add_string_option("corrector_type", "The type of corrector steps that should be taken.", "none", &[("none", "no corrector"), ("affine", "corrector step towards mu=0"), ("primal-dual", "corrector step towards current mu")], "If \"mu_strategy\" is \"adaptive\", this option determines what kind of corrector steps should be tried. Changing this option is experimental.")?;
    r.add_bool_option("skip_corr_if_neg_curv", "Whether to skip the corrector step in negative curvature iteration.", true, "The corrector step is not tried if negative curvature has been encountered during the computation of the search direction in the current iteration. This option is only used if \"mu_strategy\" is \"adaptive\". Changing this option is experimental.")?;
    r.add_bool_option("skip_corr_in_monotone_mode", "Whether to skip the corrector step during monotone barrier parameter mode.", true, "The corrector step is not tried if the algorithm is currently in the monotone mode (see also option \"barrier_strategy\"). This option is only used if \"mu_strategy\" is \"adaptive\". Changing this option is experimental.")?;
    r.add_lower_bounded_number_option("corrector_compl_avrg_red_fact", "Complementarity tolerance factor for accepting corrector step.", 0.0, true, 1.0, "This option determines the factor by which complementarity is allowed to increase for a corrector step to be accepted. Changing this option is experimental.")?;
    r.add_bounded_integer_option("soc_method", "Ways to apply second order correction", 0, 1, 0, "This option determines the way to apply second order correction, 0 is the method described in the implementation paper. 1 is the modified way which adds alpha on the rhs of x and s rows.")?;

