    r.add_lower_bounded_number_option("slack_move", "Correction size for very small slacks.", 0.0, false, (f64::EPSILON).powf(0.75), "Due to numerical issues or the lack of an interior, the slack variables might become very small. If a slack becomes very small compared to machine precision, the corresponding bound is moved slightly. This parameter determines how large the move should be. Its default value is mach_eps^{3/4}. See also end of Section 3.5 in implementation paper - but actual implementation might be somewhat different.")?;
    r.add_string_option("constraint_violation_norm_type", "Norm to be used for the constraint violation in the line search.", "1-norm", &[("1-norm", "use the 1-norm"), ("2-norm", "use the 2-norm"), ("max-norm", "use the infinity norm")], "Determines which norm should be used when the algorithm computes the constraint violation in the line search.")?;

    // ===== LimMemQuasiNewtonUpdater::RegisterOptions (Algorithm/IpLimMemQuasiNewtonUpdater.cpp) =====
    r.set_registering_category("Hessian Approximation");
    r.add_lower_bounded_integer_option("limited_memory_max_history", "Maximum size of the history for the limited quasi-Newton Hessian approximation.", 0, 6, "This option determines the number of most recent iterations that are taken into account for the limited-memory quasi-Newton approximation.")?;
    r.add_string_option(
        "limited_memory_update_type",
        "Quasi-Newton update formula for the limited memory quasi-Newton approximation.",
        "bfgs",
        &[
            ("bfgs", "BFGS update (with skipping)"),
            ("sr1", "SR1 (not working well)"),
        ],
        "",
    )?;
    r.add_string_option("limited_memory_initialization", "Initialization strategy for the limited memory quasi-Newton approximation.", "scalar1", &[("scalar1", "sigma = s^Ty/s^Ts"), ("scalar2", "sigma = y^Ty/s^Ty"), ("scalar3", "arithmetic average of scalar1 and scalar2"), ("scalar4", "geometric average of scalar1 and scalar2"), ("constant", "sigma = limited_memory_init_val"), ("history-max", "sigma = max over the stored curvature pairs of s^Ty/s^Ts")], "Determines how the diagonal Matrix B_0 as the first term in the limited memory approximation should be computed. The four scalar* values and constant are upstream Ipopt's, and read the newest curvature pair only. history-max is pounce's (gh#818): it applies the scalar1 formula to every pair in the history window and keeps the largest, so B_0 does not understate the curvature of the directions the rank-2 corrections say nothing about.")?;
    r.add_lower_bounded_number_option("limited_memory_init_val", "Value for B0 in low-rank update.", 0.0, true, 1.0, "The starting matrix in the low rank update, B0, is chosen to be this multiple of the identity in the first iteration (when no updates have been performed yet), and is constantly chosen as this value, if \"limited_memory_initialization\" is \"constant\".")?;
    r.add_lower_bounded_number_option("limited_memory_init_val_max", "Upper bound on value for B0 in low-rank update.", 0.0, true, 1e8, "The starting matrix in the low rank update, B0, is chosen to be this multiple of the identity in the first iteration (when no updates have been performed yet), and is constantly chosen as this value, if \"limited_memory_initialization\" is \"constant\".")?;
    r.add_lower_bounded_number_option("limited_memory_init_val_min", "Lower bound on value for B0 in low-rank update.", 0.0, true, 1e-8, "The starting matrix in the low rank update, B0, is chosen to be this multiple of the identity in the first iteration (when no updates have been performed yet), and is constantly chosen as this value, if \"limited_memory_initialization\" is \"constant\".")?;
    r.add_lower_bounded_integer_option("limited_memory_max_skipping", "Threshold for successive iterations where update is skipped.", 1, 2, "If the update is skipped more than this number of successive iterations, the quasi-Newton approximation is reset.")?;
    r.add_bool_option("limited_memory_special_for_resto", "Determines if the quasi-Newton updates should be special during the restoration phase.", false, "Until Nov 2010, Ipopt used a special update during the restoration phase, but it turned out that this does not work well. The new default uses the regular update procedure and it improves results. If for some reason you want to get back to the original update, set this option to \"yes\".")?;

    // ===== MonotoneMuUpdate::RegisterOptions (Algorithm/IpMonotoneMuUpdate.cpp) =====
    r.set_registering_category("Barrier Parameter Update");
    r.add_lower_bounded_number_option("mu_init", "Initial value for the barrier parameter.", 0.0, true, 0.1, "This option determines the initial value for the barrier parameter (mu). It is only relevant in the monotone, Fiacco-McCormick version of the algorithm. (i.e., if \"mu_strategy\" is chosen as \"monotone\")")?;
    r.add_lower_bounded_number_option("barrier_tol_factor", "Factor for mu in barrier stop test.", 0.0, true, 10.0, "The convergence tolerance for each barrier problem in the monotone mode is the value of the barrier parameter times \"barrier_tol_factor\". This option is also used in the adaptive mu strategy during the monotone mode. This is kappa_epsilon in implementation paper.")?;
    r.add_bounded_number_option("mu_linear_decrease_factor", "Determines linear decrease rate of barrier parameter.", 0.0, true, 1.0, true, 0.2, "For the Fiacco-McCormick update procedure the new barrier parameter mu is obtained by taking the minimum of mu*\"mu_linear_decrease_factor\" and mu^\"superlinear_decrease_power\". This is kappa_mu in implementation paper. This option is also used in the adaptive mu strategy during the monotone mode.")?;
    r.add_bounded_number_option("mu_superlinear_decrease_power", "Determines superlinear decrease rate of barrier parameter.", 1.0, true, 2.0, true, 1.5, "For the Fiacco-McCormick update procedure the new barrier parameter mu is obtained by taking the minimum of mu*\"mu_linear_decrease_factor\" and mu^\"superlinear_decrease_power\". This is theta_mu in implementation paper. This option is also used in the adaptive mu strategy during the monotone mode.")?;
    r.add_string_option("mu_allow_fast_monotone_decrease", "Allow skipping of barrier problem if barrier test is already met.", "yes", &[("no", "Take at least one iteration per barrier problem even if the barrier test is already met for the updated barrier parameter"), ("yes", "Allow fast decrease of mu if barrier test it met")], "")?;
    r.add_bounded_number_option("tau_min", "Lower bound on fraction-to-the-boundary parameter tau.", 0.0, true, 1.0, true, 0.99, "This is tau_min in the implementation paper. This option is also used in the adaptive mu strategy during the monotone mode.")?;

    // ===== OptimalityErrorConvergenceCheck::RegisterOptions (Algorithm/IpOptErrorConvCheck.cpp) =====
    r.set_registering_category("Termination");
    r.add_lower_bounded_integer_option(
        "max_iter",
        "Maximum number of iterations.",
        0,
        3000,
        "The algorithm terminates with a message if the number of iterations exceeded this number.",
    )?;
    r.add_lower_bounded_number_option("max_wall_time", "Maximum number of walltime clock seconds.", 0.0, true, 1e20, "A limit on walltime clock seconds that Ipopt can use to solve one problem. If during the convergence check this limit is exceeded, Ipopt will terminate with a corresponding message.")?;
    r.add_lower_bounded_number_option("max_cpu_time", "Maximum number of CPU seconds.", 0.0, true, 1e20, "A limit on CPU seconds that Ipopt can use to solve one problem. If during the convergence check this limit is exceeded, Ipopt will terminate with a corresponding message.")?;
    r.add_lower_bounded_number_option("dual_inf_tol", "Desired threshold for the dual infeasibility.", 0.0, true, 1.0, "Absolute tolerance on the dual infeasibility. Successful termination requires that the max-norm of the (unscaled) dual infeasibility is less than this threshold.")?;
    r.add_lower_bounded_number_option("constr_viol_tol", "Desired threshold for the constraint and variable bound violation.", 0.0, true, 1e-4, "Absolute tolerance on the constraint and variable bound violation. Successful termination requires that the max-norm of the (unscaled) constraint violation is less than this threshold. If option bound_relax_factor is not zero 0, then Ipopt relaxes given variable bounds. The value of constr_viol_tol is used to restrict the absolute amount of this bound relaxation. ")?;
    r.add_lower_bounded_number_option("compl_inf_tol", "Desired threshold for the complementarity conditions.", 0.0, true, 1e-4, "Absolute tolerance on the complementarity. Successful termination requires that the max-norm of the (unscaled) complementarity is less than this threshold.")?;
    r.add_lower_bounded_number_option("acceptable_tol", "\"Acceptable\" convergence tolerance (relative).", 0.0, true, 1e-6, "Determines which (scaled) overall optimality error is considered to be \"acceptable\". There are two levels of termination criteria. If the usual \"desired\" tolerances (see tol, dual_inf_tol etc) are satisfied at an iteration, the algorithm immediately terminates with a success message. On the other hand, if the algorithm encounters \"acceptable_iter\" many iterations in a row that are considered \"acceptable\", it will terminate before the desired convergence tolerance is met. This is useful in cases where the algorithm might not be able to achieve the \"desired\" level of accuracy.")?;
    r.add_lower_bounded_integer_option("acceptable_iter", "Number of \"acceptable\" iterates before triggering termination.", 0, 15, "If the algorithm encounters this many successive \"acceptable\" iterates (see \"acceptable_tol\"), it terminates, assuming that the problem has been solved to best possible accuracy given round-off. If it is set to zero, this heuristic is disabled.")?;
    r.add_lower_bounded_number_option("acceptable_dual_inf_tol", "\"Acceptance\" threshold for the dual infeasibility.", 0.0, true, 1e10, "Absolute tolerance on the dual infeasibility. \"Acceptable\" termination requires that the (max-norm of the unscaled) dual infeasibility is less than this threshold; see also acceptable_tol.")?;
    r.add_lower_bounded_number_option("acceptable_constr_viol_tol", "\"Acceptance\" threshold for the constraint violation.", 0.0, true, 1e-2, "Absolute tolerance on the constraint violation. \"Acceptable\" termination requires that the max-norm of the (unscaled) constraint violation is less than this threshold; see also acceptable_tol.")?;
    r.add_lower_bounded_number_option("acceptable_compl_inf_tol", "\"Acceptance\" threshold for the complementarity conditions.", 0.0, true, 1e-2, "Absolute tolerance on the complementarity. \"Acceptable\" termination requires that the max-norm of the (unscaled) complementarity is less than this threshold; see also acceptable_tol.")?;
    r.add_lower_bounded_number_option("acceptable_obj_change_tol", "\"Acceptance\" stopping criterion based on objective function change.", 0.0, false, 1e20, "If the relative change of the objective function (scaled by Max(1,|f(x)|)) is less than this value, this part of the acceptable tolerance termination is satisfied; see also acceptable_tol. This is useful for the quasi-Newton option, which has trouble to bring down the dual infeasibility.")?;
    r.add_lower_bounded_number_option("diverging_iterates_tol", "Threshold for maximal value of primal iterates.", 0.0, true, 1e20, "If any component of the primal iterates exceeded this value (in absolute terms), the optimization is aborted with the exit message that the iterates seem to be diverging.")?;
    r.add_lower_bounded_integer_option("dual_diverging_streak", "Consecutive growing-dual-infeasibility iterations before the dual-divergence guard fires (0, the default, disables it).", 0, 0, "pounce addition (pounce#246), **off by default**. When the NLP-scaled dual infeasibility grows for this many consecutive iterations in an elevated regime and is large in absolute terms, the outer routes to the restoration phase. It was added to bound a reported bad-warm-start grind on emfl050, but that justification did not hold up: the reported measurement was caller-side JAX compilation, and on the build predating the guard both emfl050 instances solve to the same optimum in the same time (see pounce#246 / pounce#250). Its measured effect over 1284 MINLPLib models is four changed outcomes, and the response is knife-edge and non-monotone in this threshold -- deb7/deb9 reach a better local optimum only at exactly 15, while pooling_rt2stp turns from Solve_Succeeded into Maximum_Iterations_Exceeded only at 10 and 15. That is basin luck on nonconvex problems, not a property, so it is not something to impose by default: the upside is a better local optimum on an already-solved problem, while the downside is a clean solve becoming a failure. Set it to a positive value (15 was the former default) to opt in; when enabled, a diversion that ends worse than a point the solve already had is undone (pounce#250 follow-up).")?;
    r.add_lower_bounded_integer_option("resto_decline_deferrals", "How many times the acceptable-point restoration decline may be deferred while the solve is still converging (0 disables the deferral).", 0, 1, "pounce addition (gh #534). When the line search fails at a point that already passes the acceptable-level tolerances, POUNCE declines to enter restoration and reports that point (upstream `IpBacktrackingLineSearch.cpp`'s ACCEPTABLE_POINT_REACHED). That guard reads the point and nothing about the trajectory that reached it, so it stops a contracting endgame and a dead stall with equal confidence -- on CUTE `eigena2` it fires while the dual infeasibility is quartering every iteration on unit steps, three iterations short of a strict certificate. With this at a positive value the decline is deferred, at most this many times per solve, when the overall NLP error has contracted by at least a factor of two on each of the last three iterations; the solve continues for up to ten more iterations, and if no strict certificate arrives the point the guard would have returned is restored and reported. The deferral is therefore bounded in cost and cannot return a worse answer than declining immediately would have. Set to 0 for the pre-#534 behaviour.")?;
    r.add_lower_bounded_number_option("resto_decline_progress_ratio", "Per-iteration contraction of the overall NLP error required before a restoration decline is deferred.", 0.0, true, 0.5, "pounce addition (gh #534), companion to `resto_decline_deferrals`. The decline is deferred only when each of the last three outer iterations cut the overall NLP error to at most this fraction of the previous one. The default 0.5 separates the cases the issue measured: `eigena2` quarters every iteration (ratio 0.249) and is deferred, while `eigenb2` (1.88e-7, 2.69e-7, 2.89e-7, 2.93e-7) and `csfi2` (8.468e-8 -> 8.524e-8 on its last step) are flat or rising and are declined exactly as before. Setting it to 1 admits any non-increasing window, and setting it very large (say 1e20) drops the progress requirement entirely, so the decline is deferred on every acceptable entry point until `resto_decline_deferrals` is spent -- the \"bypass the guard and see how far the solve gets\" experiment, which is otherwise only reachable by patching the source. The floor is held either way, so even the bypass cannot return a worse point than declining would have.")?;
    r.add_lower_bounded_integer_option("neg_curv_escapes", "How many times a certified stationary point with an indefinite reduced Hessian may be escaped along a direction of negative curvature (0 disables).", 0, 1, "pounce addition (gh #797). The filter line-search interior-point method certifies FIRST-ORDER stationarity, and on a nonconvex model that is strictly weaker than a local minimum: at a point where the reduced Hessian on null(A) is negative definite every KKT residual is zero, so the convergence test has nothing to object to and the point reported as Solve_Succeeded is a constrained MAXIMUM. The reported case is the CLI fixture nonconvex_qp.nl -- min x0*x1 s.t. x0+x1 = 2, 0 <= x <= 4, whose restriction to the feasible segment is the concave x0*(2-x0), maximized at (1,1) with f = 1 and minimized at the endpoints (0,2) and (2,0) with f = 0. From the bound-pushed start (0.01, 0.01) the first Newton step lands exactly on (1,1) and the solve stops there at obj = 1. Inertia correction does not prevent this and never could: delta_x*I is symmetric, so on a model and an iterate that are symmetric under x0 <-> x1 it cannot break the symmetry, and a symmetric correction applied to a zero gradient gives a zero step however indefinite the reduced Hessian is. Regularization makes the STEP well-posed; nothing in the algorithm asks whether the point converged to is a minimum. With this at a positive value, a certified stationary point is first tested for second-order necessity -- one extra factorization of the augmented system with the inertia check on and no perturbation, whose correct inertia is exactly the statement that W + Sigma is positive definite on null(A) -- and only a wrong inertia costs anything more. When the inertia IS wrong, delta_x is escalated until it is right and a few inverse-iteration back-solves against that factor recover the most-negative-curvature direction, which is then MEASURED rather than trusted; the solve steps along it (fraction-to-the-boundary capped, backtracked against the second-order decrease model, refused outright if it raises the constraint violation past constr_viol_tol) and continues for up to 30 more iterations. The stationary point is snapshotted first and is restored and reported unless the continuation comes back with a certificate of its own at a better point, so the escape is bounded in cost and CANNOT return a worse answer than reporting the stationary point immediately would have -- the same floor-and-deadline accounting as resto_decline_deferrals. Above 1 the floor keeps the BEST certificate the escapes have left rather than the most recent one (gh #805), so that guarantee holds at any value; each escape still buys its own continuation 30 iterations, so the cost scales with this option and the guarantee does not. On nonconvex_qp.nl the escape turns Solve_Succeeded at obj = 1 into Solve_Succeeded at obj = 0. Set to 0 for the pre-#797 behaviour: report the first-order certificate whatever its curvature. NOTE that this is a local method either way -- an escape finds a point that is second-order suspect and leaves it, it does not certify global optimality, and a stationary point whose reduced Hessian is positive definite is never touched.")?;
    r.add_lower_bounded_integer_option("limited_memory_ls_failure_restarts", "How many times a line-search failure at an already-feasible point may re-anchor the limited-memory Hessian and retry, instead of entering the restoration phase (0, the default, disables).", 0, 0, "pounce addition (gh #818). When the backtracking line search cannot accept any trial step, either the POINT is bad -- infeasible, and the restoration phase is exactly the right tool -- or the DIRECTION is, because W is a quasi-Newton model carrying curvature the iterate has left behind. Upstream has one answer for both, because restoration is the only fallback it has. At an already-feasible point that answer is a no-op: the restoration NLP minimizes the constraint violation and there is none to minimize, so it wanders at theta ~ 1e-13 and reports Restoration_Failed. Measured on the deb7 fixture under limited-memory, the solve stalls at inf_pr ~ 1e-12 with inf_du ~ 1e5, enters restoration at a point feasible to 8e-13, and spends 340 of its 1242 iterations there before failing; on an unconstrained model theta is identically zero, so restoration cannot move at all and the solve can die at iteration 1 with Error_In_Step_Computation and the objective still at its starting value. With this at a positive value, such a failure first drops every curvature pair but the newest -- keeping sigma a real Rayleigh quotient and the secant condition on the step just taken, while discarding the older corrections that made the direction unusable, which is what L-BFGS-B does on a line-search failure (col = 0 in mainlb) -- and retries the iterate. It is a rung and not a refusal: it fires only where restoration has nothing to reduce, it runs AFTER the acceptable-point decline so a reportable point is still reported, and every path that reached restoration before still reaches it once the rung is spent. The bound is structural as well as counted, since the re-anchor gives up once the history is down to one pair, so a second failure at the same iterate falls straight through. Has no effect under an exact Hessian, which has no curvature history to re-anchor. DEFAULTS TO 0, i.e. off: a line-search failure always enters restoration, as it does upstream. The rung is NOT what fixes gh #818 -- the backtracking interpolation is, and every gh #818 regression test passes with the rung compiled out. It defaulted to 1 in the first draft of that work, on a measurement taken before the interpolation was gated to fire only after the fixed sequence has already spent six trials; re-measured on top of that gate the rung takes `pooling_rt2stp` from 716 iterations to 744 and `infeasible_square_scaled_1em4` from 24 to 26 -- both of which are unmoved from `main` with it off -- and changes `deb7`'s verdict from Error_In_Step_Computation at 1010 to Restoration_Failed at 460, which is a different answer rather than a faster one. It is not all cost: at this gate `eigena2` goes from Error_In_Step_Computation at 201 to Solved_To_Acceptable_Level at 174, and `issue_508_infeasible_gap_1em4` from 79 to 76 at the same certificate. Off is the configuration that leaves every fixture where `main` has it; the case for turning it on has improved and needs its own corpus sweep to settle. It is kept because the reasoning is sound and unaddressed elsewhere (a restoration phase entered at a feasible point has no constraint violation to minimize), and some model will want it. Note that setting this at ANY value, 0 included, is not the same as leaving it alone -- it is a `TERMINATION_POLICY_OPTIONS` key, so setting it tells POUNCE the caller has an opinion about when the solve stops, which opts out of the automatic `Solved_To_Acceptable_Level` re-solve (pounce#748). The `pooling_rt2stp` fixture used to be the worked example of this (`Solve_Succeeded` in 295 iterations by default against `Solved_To_Acceptable_Level` in 362 with this set explicitly to 0); it no longer demonstrates the coupling, because that fixture's limited-memory leg now ends in Error_In_Step_Computation at 716 on `main` and so never reaches the acceptable-level ladder at all. The coupling itself is unchanged -- it is a property of the key, not of any fixture. `resto_decline_deferrals` and `neg_curv_escapes` carry the same coupling.")?;
    r.add_lower_bounded_number_option("mu_target", "Desired value of complementarity.", 0.0, false, 0.0, "Usually, the barrier parameter is driven to zero and the termination test for complementarity is measured with respect to zero complementarity. However, in some cases it might be desired to have Ipopt solve barrier problem for strictly positive value of the barrier parameter. In this case, the value of \"mu_target\" specifies the final value of the barrier parameter, and the termination tests are then defined with respect to the barrier problem for this value of the barrier parameter.")?;
    // Rapid infeasibility detection (pounce addition) — a main-loop
    // analogue of Ipopt's restoration-side LOCALLY_INFEASIBLE test.
    r.add_lower_bounded_number_option("infeas_stationarity_tol", "Stationarity tolerance for rapid infeasibility detection.", 0.0, false, 1e-8, "The main loop terminates with local infeasibility when the scaled infeasibility stationarity norm(J^T c) / max(1, norm(c)) stays at or below this value, while the constraint violation stays bounded away from zero (see infeas_viol_kappa), for infeas_max_streak successive iterations. Setting this to 0 disables rapid infeasibility detection.")?;
    r.add_lower_bounded_number_option("infeas_viol_kappa", "Constraint-violation margin for rapid infeasibility detection.", 0.0, false, 1e2, "An iterate only counts toward the infeasibility streak when its max-norm constraint violation exceeds this multiple of constr_viol_tol, or 1e-2, whichever is larger. Keeps rapid infeasibility detection from firing on nearly-feasible flat spots. The 1e-2 floor (pounce#519) is what keeps that promise when constr_viol_tol is tightened: without it the margin slides with the feasibility tolerance, so asking for stricter feasibility (constr_viol_tol = 1e-6) would let violations as small as 1e-4 count as bounded away from feasible and make the solver MORE likely to report local infeasibility. Raising this option raises the floor as usual; to switch the detector off entirely, set infeas_stationarity_tol or infeas_max_streak to 0.")?;
    r.add_lower_bounded_integer_option("infeas_max_streak", "Successive infeasible-stationary iterations before declaring local infeasibility.", 0, 5, "Number of consecutive iterations that must satisfy the rapid infeasibility detection test before the main loop terminates with local infeasibility. Setting this to 0 disables rapid infeasibility detection.")?;
    r.add_lower_bounded_number_option("primal_noise_floor_kappa", "Safety factor on the per-row floor below which a constraint residual is treated as floating-point noise by the strict convergence test and the infeasibility verdict.", 0.0, false, 64.0, "DELIBERATE DEVIATION FROM UPSTREAM IPOPT (pounce#528). The primal term of the KKT error is the one term Ipopt leaves as a bare absolute residual (the dual and complementarity terms carry s_d / s_c). But c_i = g_i(x) - b_i and d_i - s_i are each a difference of quantities the row's own size, so they are quantised in units of eps times that magnitude: no iterate can place either residual strictly between 0 and one ulp of the row. Once that quantum exceeds tol -- constraint values past ~4.5e7 at the 1e-8 default -- nlp_err <= tol stops being a statement about the iterate and becomes a bet on the residual landing on a bitwise-exact 0 rather than on one ulp. Feasible, bounded LPs then exited Search_Direction_Becomes_Too_Small holding the correct optimum. The STRICT gate therefore counts a row's residual only where it exceeds max(placement floor, this kappa times eps times the row's magnitude). pounce#590 extended the same floor to the per-component constr_viol test and to the absolute arm of rapid infeasibility detection, in both cases only when NO row rises above its own floor -- one resolvable row anywhere and the raw comparison stands. That case is exactly a point feasible to the limit the model's arithmetic can express: LyoPRONTO's Landau-coordinate lyophilisation OCP has conduction rows near 1e8, so one ulp is ~1e-2, and a solve at a scaled KKT error of 4.3e-10 was reported Infeasible_Problem_Detected on a violation that was pure quantisation. The scale-relative veto still sees the raw relative violation, and the acceptable-level band keeps the raw error. Verdicts are flat across kappa from 8 to 1024 on the measured set. Set to 0 to disable the floor and restore bit-for-bit upstream behaviour.")?;
    r.add_lower_bounded_number_option("acceptable_progress_kappa", "Fraction of acceptable_tol the error and objective may drift across the acceptable-level streak and still count as settled.", 0.0, false, 1e-1, "DELIBERATE DEVIATION FROM UPSTREAM IPOPT (pounce#533). Acceptable-level termination fires after acceptable_iter consecutive iterates under acceptable_tol, with no test for whether the solve is still moving -- so it can stop at a point that is near-stationary for the current BARRIER SUBPROBLEM while the NLP solve is still descending, returning a worse answer under a weaker status than continuing would have reached. Measured: kissing (Vanderbei) stopped at iteration 103 with objective 1.00000108 and Solved_To_Acceptable_Level, where continuing reaches 0.84544259 with a strict certificate at 550 -- 18% high, against Ipopt's 0.845442591227744; NARX_CFy (Mittelmann) stopped at 565 with both residuals near 1e-7, where 60 more iterations (25 s, inside the benchmark's 300 s limit) collapse them by five orders and beat both its own answer and Ipopt's. POUNCE therefore also requires the streak to have FLATTENED: across the acceptable_iter iterates that made it, the spread (max - min) of the KKT error must be within this fraction of acceptable_tol, and the spread of the objective within the same fraction of acceptable_tol times max(1, |f|). Spread rather than trend, because kissing's error was an order of magnitude WORSE at the iterate it stopped on than at one it had already reached inside the same streak -- it was wandering across the band, not converging inside it. Either signal alone is enough to keep solving, because kissing's objective was flat to all eight printed figures over those iterates while the continued run moved it by 15%. As with obj_scale_certificate_threshold this is a bet that is TESTED, not predicted: a refused termination is recorded, and if the continued run fails to do better it ends at exactly that point under exactly that status, so the outcome is never worse than without the mechanism -- the cost is bounded extra iterations. Set to 0 to disable the progress test and restore bit-for-bit upstream behaviour.")?;
    r.add_lower_bounded_number_option("dual_inf_scale_kappa", "Safety factor on the scale-relative floor under dual_inf_tol used by the strict convergence test.", 0.0, false, 1.0, "DELIBERATE DEVIATION FROM UPSTREAM IPOPT (pounce#532). dual_inf_tol is a bare ABSOLUTE bound on a quantity the aggregate KKT error NORMALISES: that aggregate's dual term is norm(grad L) / s_d, and s_d grows with the mean magnitude of the multipliers. On Vanderbei's orthrds2, s_d reaches 1.6e10 with norm(grad L) = 89.7 -- an aggregate dual term of 5.6e-09, comfortably inside the default tol = 1e-8 -- and the component gate refused it against 1.0, so a solve stationary to nine digits exited Solved_To_Acceptable_Level holding the answer. The same problem with its objective multiplied by a positive constant, which changes no feasible point, no solution and no active set, crosses the bound. The STRICT gate therefore judges the unscaled dual infeasibility against max(dual_inf_tol, this kappa times tol times the dual scale), where the dual scale is the magnitude of the largest term grad L is assembled from (grad f, J^T y, the bound multipliers) -- so what the floor forgives is a residual small RELATIVE to the terms that produced it, never a genuine non-stationarity: min -exp(x) s.t. x >= 0 reaching inf_du = 8.8e+47 with grad f = -8.8e47 has nothing cancelled and stays refused by eight orders. Bounded twice over: the aggregate tol gate must still pass on the same iterate, and at kappa = 1 the floor only rises above dual_inf_tol once the dual scale exceeds dual_inf_tol / tol = 1e8. Only the strict gate is affected; acceptable_dual_inf_tol is untouched. Set to 0 to disable the floor and restore bit-for-bit upstream behaviour -- also what to do if you tighten dual_inf_tol and want that absolute standard honoured unconditionally.")?;

    // Status-fidelity gate (pounce addition, pounce#173) — a post-solve
    // relabel for consumers (e.g. discopt's safe bound tightening) that
    // must not trust an OPTIMAL status on a drifted point.
    r.add_lower_bounded_number_option("obj_scale_certificate_threshold", "Objective-scale floor below which a termination certificate is re-tested rather than trusted.", 0.0, false, 1e-4, "DELIBERATE DEVIATION FROM UPSTREAM IPOPT (pounce#200). Gradient-based objective scaling can pick a factor so small (floored at nlp_scaling_min_value, 1e-8) that the scaled convergence test passes far from any KKT point: on the flat quartics quartc/dqrtic the solver certified optimality at objective 248.88 / 39.36 when the true minimum is ~0, with an unscaled dual infeasibility of 0.84. When the objective scaling factor is below this threshold AND the max-norm UNSCALED KKT error is still above acceptable_tol, POUNCE does not stop; it keeps iterating. A constant objective scale cancels out of the Newton step and the line-search tests are scale-invariant, so the run continues along the trajectory an unscaled run would take, and on a genuinely false stop it reaches the true minimum (quartc then finishes at 8.8e-07). Whether the stop was really false is NOT predicted in advance -- it is tested: if continuing achieves nothing, the refused point is restored and reported with the status it would originally have had, so the outcome is never worse than without the mechanism. Set to 0 to disable and restore bit-for-bit upstream behaviour (Ipopt itself reports quartc at 248.88 as optimal). Distinct from kkt_fidelity_tol, which is a pure relabel at termination and does not change the iteration path.")?;
    r.add_lower_bounded_number_option("kkt_fidelity_tol", "Post-solve max-norm unscaled KKT error above which Solve_Succeeded is downgraded.", 0.0, false, 0.0, "Opt-in status-fidelity check (default 0 = disabled). When positive, after the solve a reported Solve_Succeeded whose max-norm UNSCALED KKT error (max of the unscaled dual infeasibility, constraint violation, and complementarity, reported as final_unscaled_kkt_error) exceeds this threshold is downgraded to Solved_To_Acceptable_Level. This is a pure relabel at termination — it does not change the iteration path or make the solver work harder; to instead drive the solver to a tighter point, tighten dual_inf_tol / constr_viol_tol / compl_inf_tol, which gate on the same unscaled residuals. Useful when the default (scaled) convergence test passes on an ill-conditioned, nlp_scaling-deflated problem but the user-space duals have drifted.")?;

    // ===== OrigIpoptNLP::RegisterOptions (Algorithm/IpOrigIpoptNLP.cpp) =====
    r.set_registering_category("NLP");
    r.add_lower_bounded_number_option("bound_relax_factor", "Factor for initial relaxation of the bounds.", 0.0, false, 1e-8, "Before start of the optimization, the bounds given by the user are relaxed. This option sets the factor for this relaxation. Additional, the constraint violation tolerance constr_viol_tol is used to bound the relaxation by an absolute value. If it is set to zero, then then bounds relaxation is disabled. See Eqn.(35) in implementation paper. Note that the constraint violation reported by Ipopt at the end of the solution process does not include violations of the original (non-relaxed) variable bounds. See also option honor_original_bounds.")?;
    r.add_bool_option("honor_original_bounds", "Indicates whether final points should be projected into original bounds.", false, "Ipopt might relax the bounds during the optimization (see, e.g., option \"bound_relax_factor\"). This option determines whether the final point should be projected back into the user-provide original bounds after the optimization. Note that violations of constraints and complementarity reported by Ipopt at the end of the solution process are for the non-projected point.")?;
    r.set_registering_category("Warm Start");
    r.add_bool_option("warm_start_same_structure", "Indicates whether a problem with a structure identical to the previous one is to be solved.", false, "If enabled, then the algorithm assumes that an NLP is now to be solved whose structure is identical to one that already was considered (with the same NLP object).")?;
    // Upstream registers `warm_start_init_point` in
    // `IpDefaultIterateInitializer.cpp:RegisterOptions`, alongside the
    // regular (cold) initializer. Pounce's `DefaultIterateInitializer`
    // doesn't pull it from `OptionsList` directly — `AlgBuilder` reads
    // it to pick between `DefaultIterateInitializer` and
    // `WarmStartIterateInitializer` — but the option still needs to
    // appear in the registry so `--option warm_start_init_point=yes`
    // type-checks.
    r.add_bool_option("warm_start_init_point", "Warm-start for initial point", false, "Indicates whether this optimization should use a warm start initialization, where values of primal and dual variables are given (e.g., from a previous optimization of a related problem.)")?;
    r.set_registering_category("NLP");
    r.add_bool_option("check_derivatives_for_naninf", "Indicates whether it is desired to check for Nan/Inf in derivative matrices", false, "Activating this option will cause an error if an invalid number is detected in the constraint Jacobians or the Lagrangian Hessian. If this is not activated, the test is skipped, and the algorithm might proceed with invalid numbers and fail. If test is activated and an invalid number is detected, the matrix is written to output with print_level corresponding to J_MOREDETAILED (7); so beware of large output!")?;
    r.add_bool_option("grad_f_constant", "Indicates whether to assume that the objective function is linear", false, "Activating this option will cause Ipopt to ask for the Gradient of the objective function only once from the NLP and reuse this information later.")?;
    r.add_bool_option("jac_c_constant", "Indicates whether to assume that all equality constraints are linear", false, "Activating this option will cause Ipopt to ask for the Jacobian of the equality constraints only once from the NLP and reuse this information later.")?;
    r.add_bool_option("jac_d_constant", "Indicates whether to assume that all inequality constraints are linear", false, "Activating this option will cause Ipopt to ask for the Jacobian of the inequality constraints only once from the NLP and reuse this information later.")?;
    r.add_bool_option("hessian_constant", "Indicates whether to assume the problem is a QP (quadratic objective, linear constraints)", false, "Activating this option will cause Ipopt to ask for the Hessian of the Lagrangian function only once from the NLP and reuse this information later.")?;
    r.set_registering_category("Hessian Approximation");
    r.add_string_option("hessian_approximation", "Indicates what Hessian information is to be used.", "exact", &[("exact", "Use second derivatives provided by the NLP."), ("limited-memory", "Perform a limited-memory quasi-Newton approximation"), ("partitioned", "Perform a partitioned quasi-Newton approximation (one dense block per element function)"), ("finite-difference", "Recover the exact Hessian by sparse finite differences of the analytic Jacobian")], "This determines which kind of information for the Hessian of the Lagrangian function is used by the algorithm. \"partitioned\" is a pounce extension with no upstream counterpart: it keeps one small dense quasi-Newton block per element function (the objective and each constraint row, whose support is a row of the constraint Jacobian) and assembles them into a genuine sparse Hessian, so the linear solver sees the model's real block structure instead of the diagonal the limited-memory low-rank path presents. Intended for structured problems -- direct-collocation trajectory optimization above all -- where second derivatives are unavailable but the Jacobian sparsity is declared. See crates/pounce-algorithm/src/hess/partitioned_quasi_newton.rs.")?;
    r.add_string_option("partitioned_update_type", "Quasi-Newton update formula applied to each element block.", "sr1", &[("sr1", "Symmetric rank-1; carries indefinite curvature."), ("bfgs", "Powell-damped BFGS; forces each element block positive semidefinite.")], "Only used when \"hessian_approximation\" is \"partitioned\". SR1 is the default because an individual constraint is not convex: damped BFGS would force every element model PSD and the solve would then scale it by a multiplier of either sign, and the indefiniteness would never reach the inertia correction. See dev-notes/issue-131-monotone-lbfgs-stall.md for what that costs on the monolithic path.")?;
    r.add_string_option("fd_hessian_coloring", "How finite-difference probe groups are formed.", "cpr", &[("cpr", "Curtis-Powell-Reid; no two columns in a group share a row."), ("star", "Star colouring of the adjacency graph; fewer groups, but unsafe on a dense pattern.")], "Only used when \"hessian_approximation\" is \"finite-difference\". A star colouring lets an entry be read from EITHER endpoint's probe and so needs fewer groups -- 76 to 42 on the Jacobian-derived laptime pattern -- and its recovery is algebraically exact. It is NOT the default anyway, because a forward difference is not an exact Hessian-vector product: it also carries a third-derivative cross term into each row, and CPR's distance-2 property forbids the two columns that term needs from sharing a group, while a star colouring does not. Measured on laptime, star over the Jacobian pattern takes 404 iterations to a wrong objective where CPR takes 38 to the right one; over the sparser declared pattern both take 30. Group size is not the cause -- declared/star has the largest groups of the four and is fine. Use star only on a sparse declared pattern, and measure.")?;
    r.add_lower_bounded_number_option("fd_hessian_reuse_tol", "Relative movement below which the previous finite-difference Hessian is reused.", 0.0, false, 0.0, "Only used when \"hessian_approximation\" is \"finite-difference\". A rebuild costs one Jacobian evaluation per probe group, so skipping it on iterations where nothing moved is the cheapest saving available. BOTH the primal iterate and the multipliers are tested, not just x: the Lagrangian Hessian is grad^2 f + sum y_j grad^2 c_j, so a cached Hessian is stale the moment y moves even if x has not -- and the endgame of an interior-point solve is full of short steps with moving duals. 0 (the default) rebuilds every iteration.")?;
    r.add_string_option("fd_hessian_pattern", "Where the finite-difference Hessian takes its sparsity pattern from.", "declared", &[("declared", "The TNLP's declared Hessian structure, when it has one."), ("jacobian", "Derived from the Jacobian pattern alone, as the union over rows of supp(grad g) tensor supp(grad g).")], "Only used when \"hessian_approximation\" is \"finite-difference\". \"declared\" needs only the TNLP's Hessian STRUCTURE call, never its values, so it is available to a model that cannot evaluate second derivatives -- every .nl declares one through AMPL's AD. \"jacobian\" needs nothing beyond the Jacobian pattern every TNLP must declare, and is a strict superset of the true pattern: safe, since a superset costs extra probe groups and never a wrong answer, but not free -- on benchmarks/large_scale laptime it is 146267 nonzeros against the true 28000. There is deliberately no mode that guesses a subset, which would silently drop curvature.")?;
    r.add_string_option("partitioned_elements", "How the Lagrangian is split into elements for the partitioned Hessian approximation.", "per-constraint", &[("per-constraint", "One element per constraint row, plus the objective."), ("blocks", "One element per contiguous block of primal variables, modelling the Lagrangian's restriction to that block.")], "Only used when \"hessian_approximation\" is \"partitioned\". \"per-constraint\" gives each block a multiplier-independent target and assumes nothing about variable ordering, but produces as many blocks as there are constraints, each approximating a constraint Hessian with no sign structure. \"blocks\" is the partition of Asprion, Chinellato and Guzzella: a direct collocation transcription orders its variables by stage, so the Lagrangian Hessian is close to block diagonal in contiguous blocks, and the block count is the stage count rather than the constraint count. \"blocks\" defaults the update formula to damped BFGS, since the Lagrangian is the object an interior-point method wants a positive definite model of; the ordering assumption is reported rather than trusted -- POUNCE_PARTITIONED_ORACLE prints the fraction of the exact Hessian's Frobenius mass that falls inside the block pattern.")?;
    r.add_lower_bounded_integer_option("partitioned_block_size", "Target width of a primal block when \"partitioned_elements\" is \"blocks\".", 1, 64, "Only used when \"hessian_approximation\" is \"partitioned\" and \"partitioned_elements\" is \"blocks\". Should be set to the number of variables one transcription stage contributes (states times collocation points, plus controls); too small and the block misses genuine intra-stage coupling, too large and each block carries more parameters than its one curvature pair per iteration can determine.")?;
    r.add_lower_bounded_number_option("partitioned_curvature_cap", "Multiple of an element's own implied curvature that a single quasi-Newton update to its block may reach. Off by default.", 0.0, true, f64::INFINITY, "Only used when \"hessian_approximation\" is \"partitioned\". An element's secant pair implies a curvature of ||y_e||/||s_e||; this caps how far one update may move that element's block, in those same units. DEFAULT IS OFF BECAUSE EVERY FINITE VALUE MEASURED WAS WORSE THAN OFF, and non-monotonically so: on benchmarks/large_scale laptime at N=80 with max_iter=1200 (true optimum 65.462928), cap=1e1 exits ErrorInStepComputation at 1071 iterations and 65.518586, cap=1e2 hits the iteration limit at 67.202124, cap=1e6 hits it at 80.398129, and off converges in 559 iterations at 65.462802. Rejecting an update is selective: it drops exactly the elements whose curvature is moving fastest and leaves those blocks stale while their neighbours update, and the resulting inconsistent Hessian costs more than a uniformly noisy but coherent one. Kept as a knob so the effect can be re-measured against a different element decomposition; do not enable it without measuring.")?;
    r.add_lower_bounded_integer_option("partitioned_max_element", "Widest element that keeps a dense block under the partitioned Hessian approximation.", 1, 64, "Only used when \"hessian_approximation\" is \"partitioned\". An element with k nonzeros costs k(k+1)/2 stored reals, so a constraint row (or objective) touching a large share of the variables would dominate the memory. Elements wider than this degrade to a diagonal approximation satisfying the weak secant condition rather than being dropped, so a separable objective is still represented exactly and a coupled one approximately.")?;
    r.add_string_option(
        "hessian_approximation_space",
        "Indicates in which subspace the Hessian information is to be approximated.",
        "nonlinear-variables",
        &[
            (
                "nonlinear-variables",
                "only in space of nonlinear variables.",
            ),
            (
                "all-variables",
                "in space of all variables (without slacks)",
            ),
        ],
        "",
    )?;

    // ===== OrigIterationOutput::RegisterOptions (Algorithm/IpOrigIterationOutput.cpp) =====
    r.set_registering_category("Output");
    r.set_registering_category("Output");
    r.add_bool_option("print_info_string", "Enables printing of additional info string at end of iteration output.", false, "This string contains some insider information about the current iteration. For details, look for \"Diagnostic Tags\" in the Ipopt documentation.")?;
    r.add_string_option("inf_pr_output", "Determines what value is printed in the \"inf_pr\" output column.", "original", &[("internal", "max-norm of violation of internal equality constraints"), ("original", "maximal constraint violation in original NLP")], "Ipopt works with a reformulation of the original problem, where slacks are introduced and the problem might have been scaled. The choice \"internal\" prints out the constraint violation of this formulation. With \"original\" the true constraint violation in the original NLP is printed.")?;
    r.add_lower_bounded_integer_option("print_frequency_iter", "Determines at which iteration frequency the summarizing iteration output line should be printed.", 1, 1, "Summarizing iteration output is printed every print_frequency_iter iterations, if at least print_frequency_time seconds have passed since last output.")?;
    r.add_lower_bounded_number_option("print_frequency_time", "Determines at which time frequency the summarizing iteration output line should be printed.", 0.0, false, 0.0, "Summarizing iteration output is printed if at least print_frequency_time seconds have passed since last output and the iteration number is a multiple of print_frequency_iter.")?;
